    $singles[chr($code)] = $count;
}

$alphabet = array_keys($singles);
$pairs = [];
$incoming = array_fill_keys($alphabet, 0);

/*
 * Distinct-character pairs cannot overlap themselves, so substr_count()
 * counts them exactly using PHP's native string-search implementation.
 */
foreach ($alphabet as $a) {
    foreach ($alphabet as $b) {
        if ($a === $b) {
            continue;
        }

        $pair = $a . $b;
        $count = substr_count($sequence, $pair);
        $incoming[$b] += $count;

        if ($count > 0) {
